"""决战策略决策逻辑（纯逻辑，不执行 UI 操作）。

本模块是 v6 决战契约的“纯逻辑层”：

- 买船优先级：考文垂（仅 6-1 A 且未持有）> U-47 > U-1206 > 其他潜艇；
- 编队：6-1 A 只上考文垂、C 点下掉，未满编留空不凑数；
- 阵型：夜战关键点梯形，其余复纵；
- 节点：保留 ``chr(ord(node)+1)``，未知节点 ``U`` 不推进；
- 技能：按配置的触发等级依次使用，买经验循环只依赖余额/灰按钮/弹窗。

所有策略参数来自 :class:`~autowsgr.infra.DecisiveConfig`，本模块不写
``if node == 'A'`` 之类的硬编码。
"""

from __future__ import annotations

import enum
from dataclasses import dataclass
from typing import TYPE_CHECKING

from autowsgr.types import FleetSelection, Formation

from .config import MapData


if TYPE_CHECKING:
    from collections.abc import Callable, Mapping

    from autowsgr.infra import DecisiveConfig

    from .state import DecisiveState


# ═══════════════════════════════════════════════════════════════════════════════
# 纯逻辑结果类型
# ═══════════════════════════════════════════════════════════════════════════════


class SortieMode(enum.Enum):
    """出征方式。"""

    QUICK = 'quick'
    """满 6 艘潜艇：直接点“出征”。"""

    MANUAL = 'manual'
    """未满编 / 6-3 J / 需要换船：编队 → 全部修理 → 开始出征。"""


@dataclass(frozen=True)
class SortiePlan:
    """一次出征的准备方案。"""

    mode: SortieMode
    reason: str
    use_instructor_skill: bool = False


class BuyExpDecision(enum.Enum):
    """买经验循环的下一步决策。"""

    BUY = 'buy'
    STOP_SCORE = 'stop_score'
    STOP_FULL = 'stop_full'
    STOP_POPUP = 'stop_popup'
    STOP_GUARD = 'stop_guard'


@dataclass(frozen=True)
class BuyExpOutcome:
    """买经验循环的结果。"""

    clicks: int
    score: int
    level: int
    stop_reason: BuyExpDecision


# ═══════════════════════════════════════════════════════════════════════════════
# 决策模块
# ═══════════════════════════════════════════════════════════════════════════════


class DecisiveLogic:
    """决战策略决策模块。

    Parameters
    ----------
    config:
        决战配置（不变量）。
    state:
        决战运行状态（共享引用，只读取，不修改）。
    """

    def __init__(
        self,
        config: DecisiveConfig,
        state: DecisiveState,
        ctx: object | None = None,
    ) -> None:
        self.config = config
        self.state = state
        # 保留 ctx 参数以兼容既有构造点；纯逻辑不再查询舰船注册表。
        self._ctx = ctx
        self._pool = list(dict.fromkeys(name for name in config.submarine_pool if name))

    # ── 战备舰队购买 ───────────────────────────────────────────────────

    def choose_purchases(
        self,
        selections: Mapping[str, FleetSelection],
        *,
        score: int | None = None,
    ) -> list[str]:
        """按优先级选择购买目标。

        规则：
        1. 6-1 A 且未持有考文垂 → 考文垂最高优先级；
        2. 未持有的 must_have（U-47 / U-1206）优先；
        3. 未满 6 艘潜艇 → 其他未持有潜艇；
        4. 已满 6 艘 → 只重复购买已持有潜艇（同名强化）。

        按优先级依次购买“当前余额还够”的目标：能买两张就买两张，
        不会因为更后面的目标买不起而退化成只买第一张。
        """
        budget = self.state.score if score is None else int(score)
        if budget <= 0:
            return []

        available = {
            name: sel
            for name, sel in selections.items()
            if name in self._pool or name == self.config.opening_ship
        }
        owned = set(self.state.ship_levels)
        priority: list[str] = []

        opening = self.config.opening_ship
        if self.is_opening_purchase_point():
            # 开局只买“考文垂 + U-47/U-1206”，不在这里浪费点数买其他潜艇；
            # 其他潜艇留到 B/C 点购买。
            if opening and opening not in owned and opening in available:
                priority.append(opening)
            for name in self.config.must_have:
                if name and name not in owned and name in available and name not in priority:
                    priority.append(name)
        else:
            for name in self.config.must_have:
                if name and name not in owned and name in available and name not in priority:
                    priority.append(name)

            if self.target_fleet_complete():
                for name in self._pool:
                    if name in owned and name in available and name not in priority:
                        priority.append(name)
            else:
                quota = self.other_new_ship_quota()
                for name in self._pool:
                    if (
                        quota > 0
                        and name not in owned
                        and name in available
                        and name not in priority
                    ):
                        priority.append(name)
                        quota -= 1

        result: list[str] = []
        remaining = budget
        for name in priority:
            cost = available[name].cost
            if cost <= remaining:
                result.append(name)
                remaining -= cost
        return result

    # ── 编队 ───────────────────────────────────────────────────────────

    def submarine_count(self) -> int:
        """当前拥有的潜艇种类数量（同名强化不重复计数）。"""
        return sum(1 for name in self._pool if name in self.state.ship_levels)

    def missing_must_have(self) -> list[str]:
        """尚未拥有的 U-47 / U-1206。"""
        return [
            name
            for name in self.config.must_have
            if name and name not in self.state.ship_levels
        ]

    def target_fleet_complete(self) -> bool:
        """是否已凑齐“6 艘潜艇且包含全部 must_have”。"""
        return (
            self.submarine_count() >= self.config.goal_count
            and not self.missing_must_have()
        )

    def other_new_ship_quota(self) -> int:
        """当前最多还能买几艘「非必须」新潜艇。

        必须给 U-47/U-1206 预留槽位：例如已有 4 艘、缺 U-47 时，
        6 个位置里只能再买 1 艘普通潜艇，另 1 个位置必须留给 U-47。
        """
        slots = max(0, self.config.goal_count - self.submarine_count())
        return max(0, slots - len(self.missing_must_have()))

    def can_buy_other_new_ship(self) -> bool:
        """是否至少还能买 1 艘非必须新潜艇。"""
        return self.other_new_ship_quota() > 0

    def _owned_submarines(self) -> list[str]:
        """按“必须潜艇优先”返回已拥有潜艇，保证截断到 6 艘时不丢。"""
        must = [
            name
            for name in self.config.must_have
            if name and name in self.state.ship_levels
        ]
        return [
            *must,
            *[
                name
                for name in self._pool
                if name in self.state.ship_levels and name not in must
            ],
        ]

    def is_opening_point(self) -> bool:
        """当前是否为开局船生效节点（6-1 A）。"""
        return (
            self.state.chapter == self.config.chapter
            and self.state.stage == self.config.opening_stage
            and self.state.node == self.config.opening_node
        )

    def is_opening_purchase_point(self) -> bool:
        """购买页阶段是否应按开局船优先。

        首次进入 6-1 时购买弹窗会先于节点识别出现（node 仍为 ``U``），
        此时也必须优先买考文垂，不能等到识别出 A 才生效。
        """
        return (
            self.state.chapter == self.config.chapter
            and self.state.stage == self.config.opening_stage
            and self.state.node in {self.config.opening_node, 'U'}
        )

    def has_affordable_ship(
        self,
        selections: Mapping[str, FleetSelection],
        *,
        score: int | None = None,
    ) -> bool:
        """购买页是否存在余额足够的“船只”卡（技能卡不算）。"""
        budget = self.state.score if score is None else int(score)
        return any(
            (name in self._pool or name == self.config.opening_ship)
            and sel.cost <= budget
            for name, sel in selections.items()
        )

    def opening_ready(self) -> bool:
        """开局是否已满足“考文垂 + U-47/U-1206 至少一艘”。"""
        if not self.is_opening_purchase_point():
            return False
        opening = self.config.opening_ship
        opening_ok = not opening or opening in self.state.ship_levels
        required = [name for name in self.config.must_have if name]
        must_ok = not required or any(
            name in self.state.ship_levels for name in required
        )
        return opening_ok and must_ok

    def opening_offer_complete(self, selections: Mapping[str, FleetSelection]) -> bool:
        """当前购买页 + 已拥有舰船是否已凑齐开局两艘。"""
        if not self.is_opening_purchase_point():
            return True
        opening = self.config.opening_ship
        opening_ok = (
            not opening
            or opening in self.state.ship_levels
            or opening in selections
        )
        required = [name for name in self.config.must_have if name]
        must_ok = not required or any(
            name in self.state.ship_levels or name in selections for name in required
        )
        return opening_ok and must_ok

    def is_opening_drop_point(self) -> bool:
        """当前是否为开局船下阵节点（C 点）。"""
        return (
            self.state.chapter == self.config.chapter
            and self.state.stage == self.config.opening_stage
            and self.state.node == self.config.drop_opening_node
        )

    def is_before_opening_drop_point(self) -> bool:
        """是否处于「C 点之前」——只有 A/B 两个节点。

        不能用 ``node != C``：D/E/... 也会满足，导致考文垂在 C 点下阵后
        又被重新上阵。这里按节点字母顺序严格比较。
        """
        if (
            self.state.chapter != self.config.chapter
            or self.state.stage != self.config.opening_stage
        ):
            return False
        node = self.state.node
        drop = self.config.drop_opening_node
        if not node or not drop or node == 'U':
            return False
        return node < drop

    def get_best_fleet(self) -> list[str]:
        """计算最优编队（长度 7，索引 0 留空）。

        - 6-1 A：有考文垂则只上考文垂；没有则留空（由上层撤退重刷）。
        - 6-1 A 之后、C 点之前：保留考文垂 + 潜艇，最多 6 艘。
        - C 点及之后：只上潜艇，未满编留空。
        """
        opening = self.config.opening_ship
        owned_subs = self._owned_submarines()
        ships: list[str] = []

        opening_owned = bool(opening) and opening in self.state.ship_levels
        before_drop = opening_owned and self.is_before_opening_drop_point()

        if self.is_opening_point():
            ships = [opening] if opening_owned else []
        elif before_drop and self.state.stage == self.config.opening_stage:
            ships = [opening, *owned_subs]
        else:
            ships = list(owned_subs)

        # 去重并截断到 6 艘；未满编时保留空槽，不用非潜艇凑数。
        ships = [name for name in dict.fromkeys(ships) if name]
        ships = ships[:6]

        for flag_ship in self.config.flagship_priority:
            if flag_ship in ships:
                ships.remove(flag_ship)
                ships.insert(0, flag_ship)
                break

        best = ['', *ships]
        while len(best) < 7:
            best.append('')
        return best

    def must_retreat(self, fleet: list[str]) -> bool:
        """舰船不足时应当撤退。

        ``min_ships_by_node`` 防止 6-1 A 只上考文垂（1 艘）时被误判撤退。
        """
        if self.is_opening_point() and self.config.opening_ship:
            if self.config.opening_ship not in self.state.ship_levels:
                return True
            # 期望开局是“考文垂 + U-47/U-1206 至少一艘”。
            # 如果只买到考文垂，必须撤退重刷，不能带着空潜艇池继续前进。
            required = [name for name in self.config.must_have if name]
            if required and not any(name in self.state.ship_levels for name in required):
                return True

        ship_count = sum(1 for name in fleet[1:] if name)
        minimum = self.config.min_ships_by_node.get(
            self.state.node,
            self.config.default_min_ships,
        )
        return ship_count < minimum

    def should_retreat(self, fleet: list[str]) -> bool:
        """兼容旧调用点的别名。"""
        return self.must_retreat(fleet)

    # ── 节点 / 关卡 ────────────────────────────────────────────────────

    def is_stage_end(self, node: str | None = None) -> bool:
        """判断当前节点是否为该小关的终止节点。"""
        if node is None:
            node = self.state.node
        return MapData.is_stage_end(
            self.config.chapter,
            self.state.stage,
            node,
        )

    def is_key_point(self, node: str | None = None) -> bool:
        """判断当前节点是否为关键点 (需夜战)。"""
        if node is None:
            node = self.state.node
        return MapData.is_key_point(
            self.config.chapter,
            self.state.stage,
            node,
        )

    def should_retreat_after_purchase_close(self) -> bool:
        """购买页关闭后是否需要撤退重刷。

        只有 E6-2 A 有这个特殊语义：该点没有可买目标时关闭购买页，
        然后撤退重刷整个第 2 小关；其他节点关闭后继续。
        """
        return (
            self.state.stage == self.config.no_target_retreat_stage
            and self.state.node == self.config.opening_node
        )

    def should_pursue_night(self, node: str | None = None) -> bool:
        """关键点默认追击夜战；配置排除的节点（E6-1 B）选择不追击。"""
        current = self.state.node if node is None else node
        if not self.is_key_point(current):
            return False
        excluded = self.config.night_pursue_excluded.get(self.state.stage, [])
        return current not in excluded

    def next_node(self, node: str | None = None) -> str:
        """节点递进：保留字母硬加；未知节点 ``U`` 保持 ``U``。"""
        current = self.state.node if node is None else node
        if not current or current == 'U':
            return 'U'
        return chr(ord(current) + 1)

    def advance_card_index(self) -> int:
        """路线固定，永远走最上方/第一个前进点。"""
        return 0

    def get_advance_choice(self, options: list[str] | None = None) -> int:  # noqa: ARG002
        """兼容旧调用点：永远返回 0。"""
        return 0

    # ── 阵型 ───────────────────────────────────────────────────────────

    def get_formation(self) -> Formation:
        """夜战关键点梯形，其余复纵；不依赖敌方编成。"""
        if self.is_key_point():
            return self.config.key_point_formation
        return self.config.default_formation

    # ── 副官 / 技能 / 买经验 ───────────────────────────────────────────

    def instructor_for_stage(self, stage: int | None = None) -> str:
        """返回该小关应使用的副官。"""
        target_stage = self.state.stage if stage is None else stage
        return self.config.instructor_by_stage.get(target_stage, '')

    def next_skill_threshold(self) -> int | None:
        """返回当前可用的最小未用技能等级；无则 ``None``。"""
        instructor = self.state.instructor or self.instructor_for_stage()
        thresholds = self.config.instructor_skill_levels.get(instructor, [])
        for threshold in sorted(set(thresholds)):
            if (
                threshold not in self.state.skill_used_levels
                and self.state.instructor_level >= threshold
            ):
                return threshold
        return None

    def should_use_kearsarge_skill(self) -> bool:
        """当前是否需要在使用技能后手动修理再出征（6-3 J）。"""
        target_node = self.config.instructor_skill_before_node.get(self.state.stage)
        if target_node != self.state.node:
            return False
        expected = self.config.instructor_by_stage.get(self.state.stage, '')
        return not self.state.instructor or self.state.instructor == expected

    def buy_exp_decision(
        self,
        *,
        score: int,
        level: int,
        disabled: bool,
        popup: bool = False,
    ) -> BuyExpDecision:
        """买经验循环的单步决策。"""
        if popup:
            return BuyExpDecision.STOP_POPUP
        if disabled or level >= self.config.instructor_max_level:
            return BuyExpDecision.STOP_FULL
        if score < self.config.buy_exp_cost:
            return BuyExpDecision.STOP_SCORE
        return BuyExpDecision.BUY

    @staticmethod
    def run_buy_exp_loop(
        *,
        initial_score: int,
        initial_level: int,
        cost: int,
        max_level: int,
        max_clicks: int,
        read_score: Callable[[], int | None],
        read_level: Callable[[], int | None],
        is_disabled: Callable[[], bool],
        click_buy: Callable[[], None],
        handle_popup: Callable[[], bool],
    ) -> BuyExpOutcome:
        """执行买经验循环（I/O 通过回调注入，便于单测）。

        终止条件：余额不足、按钮变灰/满级、点数不足弹窗、安全上限。
        每次点击后重新读取余额与等级；读取失败时用本地扣减兜底。
        """
        score = initial_score
        level = initial_level
        clicks = 0
        unchanged = 0
        reason = BuyExpDecision.STOP_GUARD

        while clicks < max_clicks:
            if is_disabled() or level >= max_level:
                reason = BuyExpDecision.STOP_FULL
                break
            if score < cost:
                reason = BuyExpDecision.STOP_SCORE
                break

            prev_score = score
            prev_level = level
            click_buy()
            clicks += 1

            if handle_popup():
                reason = BuyExpDecision.STOP_POPUP
                break

            new_score = read_score()
            score = new_score if new_score is not None else max(0, score - cost)
            new_level = read_level()
            if new_level is not None:
                level = new_level

            # 按钮不可点/点击未生效：连续两次 OCR 都没变化就停止，
            # 不能靠像素颜色猜“满级”（地图左下按钮本来就是深蓝底）。
            if (
                new_score is not None
                and new_level is not None
                and new_score == prev_score
                and new_level == prev_level
            ):
                unchanged += 1
                if unchanged >= 2:
                    reason = BuyExpDecision.STOP_FULL
                    break
            else:
                unchanged = 0

        return BuyExpOutcome(
            clicks=clicks,
            score=score,
            level=level,
            stop_reason=reason,
        )

    def refresh_allowed(self) -> bool:
        """本节点购买页是否还允许刷新。"""
        return self.state.refresh_count < self.config.max_refresh_per_node

    # ── 出征方式 ───────────────────────────────────────────────────────

    @staticmethod
    def _normalized_fleet(fleet: list[str] | None) -> list[str]:
        if fleet is None:
            return []
        return [name or '' for name in fleet[1:7]]

    def fleet_matches(self, current: list[str] | None, target: list[str] | None) -> bool:
        """当前实际编队是否与目标编队一致（空槽也算）。"""
        return self._normalized_fleet(current) == self._normalized_fleet(target)

    def needs_manual_flow(
        self,
        fleet: list[str],
        *,
        current_fleet: list[str] | None = None,
    ) -> bool:
        """是否需要走“编队 → 全部修理 → 开始出征”。"""
        if self.should_use_kearsarge_skill():
            return True
        if self.submarine_count() < self.config.goal_count:
            return True
        if self.config.opening_ship and self.config.opening_ship in fleet[1:]:
            return True
        if current_fleet is not None and not self.fleet_matches(current_fleet, fleet):
            # 例如 C 点要下掉考文垂：即使已有 6 艘潜艇，也必须先换编队。
            return True
        return False

    def sortie_plan(
        self,
        fleet: list[str],
        *,
        current_fleet: list[str] | None = None,
    ) -> SortiePlan:
        """生成出征方案。"""
        if self.should_use_kearsarge_skill():
            return SortiePlan(
                SortieMode.MANUAL,
                'instructor_skill_before_node',
                use_instructor_skill=True,
            )
        if self.submarine_count() < self.config.goal_count:
            return SortiePlan(SortieMode.MANUAL, 'fewer_than_goal_submarines')
        if self.config.opening_ship and self.config.opening_ship in fleet[1:]:
            return SortiePlan(SortieMode.MANUAL, 'opening_ship_still_deployed')
        if current_fleet is not None and not self.fleet_matches(current_fleet, fleet):
            return SortiePlan(SortieMode.MANUAL, 'fleet_mismatch')
        return SortiePlan(SortieMode.QUICK, 'full_submarine_fleet')
